// One <symbol> per icon, emitted once into the document so every icon after it
// is a ~40-byte <use> rather than a repeated copy of the path. Hidden with
// both an attribute and inline style: display:none on the <svg> is what keeps
// the sprite from taking up a line box at the top of the panel.
function spriteHtml() {
  const symbols = Object.entries(ICONS)
    .map(([name, i]) => `<symbol id="i-${name}" viewBox="${i.viewBox}"><path d="${i.path}"/></symbol>`)
    .join('');
  return `<svg xmlns="http://www.w3.org/2000/svg" style="display:none" aria-hidden="true" id="iconSprite">${symbols}</svg>`;
}

// An icon as markup. Decorative by default (aria-hidden) because every icon in
// Navy sits next to its own text label or on a button that already carries an
// aria-label — an icon that announced itself as well would say everything
// twice. Pass a label only where the icon is genuinely the only content.
function icon(name, cls = '', label = '') {
  // The name reaches an href attribute, and one call site takes it from a
  // slash-command definition a repository can write — so anything that is not
  // an icon id is dropped rather than trusted. An unknown-but-clean name simply
  // renders nothing, which is the right failure for a decorative glyph.
  const id = String(name).replace(/[^a-z0-9-]/g, '');
  const className = cls ? 'icon ' + cls : 'icon';
  const a11y = label ? `role="img" aria-label="${label}"` : 'aria-hidden="true"';
  return `<svg class="${className}" ${a11y}><use href="#i-${id}"/></svg>`;
}

module.exports = { ICONS, spriteHtml, icon };
